import sys

largeNumber = int(1e6)
cache = None
numString = None

def recursiveGet(index, posCount, negCount, carryVal):
    global cache, numString
    trueCarry = carryVal - 50
    if index == 17:
        if posCount + negCount + trueCarry == 0:
            return 0
        else:
            return largeNumber
    if cache[index][posCount][negCount][carryVal] != -1:
        return cache[index][posCount][negCount][carryVal]
    minRes = largeNumber
    for p in range(min(15, posCount) + 1):
        for n in range(min(15, negCount) + 1):
            sum_val = posCount - negCount + trueCarry
            digit = (sum_val % 10 + 10) % 10
            nextCarry = (sum_val // 10) if sum_val > 0 else ((sum_val - 9) // 10)
            if digit != int(numString[index]):
                continue
            res = recursiveGet(index + 1, posCount - p, negCount - n, nextCarry + 50) + (p + n) * (index + 1)
            if res < minRes:
                minRes = res
    cache[index][posCount][negCount][carryVal] = minRes
    return minRes

def main():
    global cache, numString
    inputNumber = int(sys.stdin.read().strip())
    maxSize = 50
    cache = [[[[-1 for _ in range(100)] for _ in range(maxSize)] for _ in range(maxSize)] for _ in range(20)]
    numString = str(inputNumber)
    while len(numString) < 17:
        numString = "0" + numString
    numString = numString[::-1]
    minAnswer = largeNumber
    for p in range(maxSize):
        for n in range(maxSize):
            res = recursiveGet(0, p, n, 50)
            if res < minAnswer:
                minAnswer = res
    print(minAnswer)

if __name__ == "__main__":
    main()

